def encode(strs):
    return "".join(s.replace("/", "//") + "/:" for s in strs)

def decode(s):
    out, cur, i = [], [], 0
    while i < len(s):
        if s[i] == "/":
            if s[i + 1] == "/":
                cur.append("/")
            else:                               # "/:" ends a string
                out.append("".join(cur))
                cur = []
            i += 2
        else:
            cur.append(s[i])
            i += 1
    return out

def encode(strs):
    return "".join(f"{len(s)}#{s}" for s in strs)

def decode(s):
    out, i = [], 0
    while i < len(s):
        j = s.index("#", i)
        length = int(s[i:j])
        out.append(s[j + 1:j + 1 + length])
        i = j + 1 + length
    return out
